    n &= 7;
    y = y - z + n * 0.25;
    switch (n) {
        case 0: y = KernelSin(pi * y, 0.0, 0); break;
        case 1:
        case 2: y = KernelCos(pi * (0.5 - y), 0.0); break;
        case 3:
        case 4: y = KernelSin(pi * (1.0 - y), 0.0, 0); break;
        case 5:
        case 6: y = -KernelCos(pi * (y - 1.5), 0.0); break;
        default: y = KernelSin(pi * (y - 2.0), 0.0, 0); break;
    }
    return -y;
