    switch (RemPio2(x, y) & 3) {
        case 0: return KernelSin(y[0], y[1], 1);
        case 1: return KernelCos(y[0], y[1]);
        case 2: return -KernelSin(y[0], y[1], 1);
        default: return -KernelCos(y[0], y[1]);
    }
